parameters.jsCode:
// Card 3 checks in code. Failures are blocked BEFORE approval.
const cal = $('Next week\'s calendar').item.json;
const banned = String(cal.banned_phrases || '').split(',').map(s => s.trim().toLowerCase()).filter(Boolean);
const versions = (($json.output || $json).versions || []).map(v => {
  const caption = String(v.caption || '') + ((v.hashtags || []).length ? '\n' + v.hashtags.map(h => '#' + String(h).replace(/^#/, '')).join(' ') : '');
  const problems = [];
  if (v.platform === 'instagram' && !cal.media_url) problems.push('Instagram needs a photo');
  if (v.platform === 'x' && caption.length > 280) problems.push('X caption ' + caption.length + ' > 280');
  if (v.platform === 'instagram' && caption.length > 2200) problems.push('Instagram caption too long');
  if (banned.some(b => caption.toLowerCase().includes(b))) problems.push('banned phrase');
  const prices = (caption.match(/₦\s?[\d,]+/g) || []).map(p => Number(p.replace(/[^\d]/g, '')));
  if (prices.some(p => p !== Number(cal.price_ngn))) problems.push('price not on today\'s list');
  if (cal.in_stock === false && v.uses_price) problems.push('product out of stock');
  return { platform: v.platform, caption, alt_text: v.alt_text || '', uses_price: !!v.uses_price || prices.length > 0, problems };
});
return { json: { calendar_id: cal.id, post_date: cal.post_date, post_time: cal.post_time, media_url: cal.media_url,
  price_ngn: cal.price_ngn, idea: cal.idea, versions, ok_count: versions.filter(v => !v.problems.length).length } };

