parameters.query:
WITH u AS (UPDATE posts SET status = 'approved', approved_by = 'Tolu', approved_at = now()
           WHERE calendar_id = $1 AND status = 'pending' RETURNING id)
UPDATE calendar SET status = 'approved' WHERE id = $1 RETURNING (SELECT count(*) FROM u) AS approved_versions;
